SELECT
    a.*,
    t.TYPE_NAME as PARTNER_TYPE_NAME
FROM TC_PARTNER_ARCHIVE a
LEFT JOIN TBL_TREASURY_PARTNER_TYPE t ON a.PARTNER_TYPE_ID = CAST(t.PARTNER_TYPE_ID AS VARCHAR(32))


        AND a.PARTNER_CODE LIKE CONCAT('%', #{params.partnerCode}, '%')


        AND a.PARTNER_NAME LIKE CONCAT('%', #{params.partnerName}, '%')


        AND a.PARTNER_TYPE_ID = #{params.partnerTypeId}


        AND a.UNIFIED_SOCIAL_CREDIT_CODE LIKE CONCAT('%', #{params.unifiedCreditCode}, '%')


        AND a.COOPERATION_STATUS = #{params.partnerStatus}


        AND a.RISK_LEVEL = #{params.riskLevel}


        AND a.STATUS = #{params.status}


ORDER BY a.CREATE_TIME DESC

SELECT COUNT(1) FROM TC_PARTNER_ARCHIVE
WHERE PARTNER_CODE = #{partnerCode}

    AND ID != #{excludeId}

SELECT COUNT(1) FROM TC_PARTNER_ARCHIVE
WHERE UNIFIED_SOCIAL_CREDIT_CODE = #{unifiedSocialCreditCode}

    AND ID != #{excludeId}

