PARTNER_CODE = #{partnerCode}, PARTNER_NAME = #{partnerName}, PARTNER_SHORT_NAME = #{partnerShortName}, PARTNER_EN_NAME = #{partnerEnName}, PARTNER_TYPE_ID = #{partnerTypeId}, UNIFIED_SOCIAL_CREDIT_CODE = #{unifiedSocialCreditCode}, LEGAL_REPRESENTATIVE = #{legalRepresentative}, REGISTERED_CAPITAL = #{registeredCapital}, ESTABLISHMENT_DATE = #{establishmentDate}, BUSINESS_TERM_START = #{businessTermStart}, BUSINESS_TERM_END = #{businessTermEnd}, REGISTERED_ADDRESS = #{registeredAddress}, OFFICE_ADDRESS = #{officeAddress}, BUSINESS_SCOPE = #{businessScope}, MAIN_BUSINESS = #{mainBusiness}, INDUSTRY_CLASSIFICATION = #{industryClassification}, ENTERPRISE_SCALE = #{enterpriseScale}, CONTACT_PHONE = #{contactPhone}, FAX_NUMBER = #{faxNumber}, EMAIL = #{email}, WEBSITE = #{website}, PAID_IN_CAPITAL = #{paidInCapital}, ASSET_SCALE = #{assetScale}, ANNUAL_REVENUE = #{annualRevenue}, CREDIT_RATING = #{creditRating}, RISK_LEVEL = #{riskLevel}, COOPERATION_START_DATE = #{cooperationStartDate}, COOPERATION_STATUS = #{cooperationStatus}, STATUS = #{status}, REMARK = #{remark}, UPDATE_TIME = #{updateTime}, UPDATE_USER = #{updateUser},
WHERE ID = #{id}
